  'Tell viewers about your channel...' => 'உங்கள் சேனலைப் பற்றி பார்வையாளர்களிடம் கூறுங்கள்...',
  'Add an about section so viewers know what your channel is about.' => 'உங்கள் சேனல் எதைப் பற்றியது என்பதை பார்வையாளர்கள் அறிந்துகொள்ள, ஒரு பற்றி பகுதியைச் சேர்க்கவும்.',
  'This channel has not added an about section yet.' => 'இந்தச் சேனல் இதுவரை பற்றிய பகுதியைச் சேர்க்கவில்லை.',
  'Admin' => 'நிர்வாகி',
