  'Monitor platform activity, moderation, revenue, and system health.' => 'பிளாட்ஃபார்ம் செயல்பாடு, கட்டுப்பாடு, வருவாய் மற்றும் கணினி ஆரோக்கியத்தை கண்காணிக்கவும்.',
  'Manage and monitor platform users, permissions, and activity.' => 'இயங்குதளப் பயனர்கள், அனுமதிகள் மற்றும் செயல்பாடுகளை நிர்வகிக்கவும் கண்காணிக்கவும்.',
  'Manage creators, channel performance, verification, and creator growth.' => 'படைப்பாளிகள், சேனல் செயல்திறன், சரிபார்ப்பு மற்றும் கிரியேட்டர் வளர்ச்சி ஆகியவற்றை நிர்வகிக்கவும்.',
  'Manage videos, shorts, posts, and content moderation across the platform.' => 'தளம் முழுவதும் வீடியோக்கள், குறும்படங்கள், இடுகைகள் மற்றும் உள்ளடக்க மதிப்பீட்டை நிர்வகிக்கவும்.',
  'Monitor live sessions, scheduling, stream health, and live moderation.' => 'நேரலை அமர்வுகள், திட்டமிடல், ஸ்ட்ரீம் ஆரோக்கியம் மற்றும் நேரலை மிதப்படுத்துதல் ஆகியவற்றைக் கண்காணிக்கவும்.',
  'Review flagged content, user complaints, and platform safety incidents.' => 'கொடியிடப்பட்ட உள்ளடக்கம், பயனர் புகார்கள் மற்றும் இயங்குதள பாதுகாப்பு சம்பவங்களை மதிப்பாய்வு செய்யவும்.',
  'Track revenue, payouts, subscriptions, ads, tips, and creator earnings.' => 'வருவாய், பணம் செலுத்துதல், சந்தாக்கள், விளம்பரங்கள், உதவிக்குறிப்புகள் மற்றும் படைப்பாளர் வருவாய் ஆகியவற்றைக் கண்காணிக்கவும்.',
  'Analyze platform growth, viewer behavior, engagement, and content performance.' => 'இயங்குதள வளர்ச்சி, பார்வையாளர் நடத்தை, ஈடுபாடு மற்றும் உள்ளடக்க செயல்திறன் ஆகியவற்றை பகுப்பாய்வு செய்யுங்கள்.',
  'Manage support tickets, help requests, escalations, and response quality.' => 'ஆதரவு டிக்கெட்டுகள், உதவி கோரிக்கைகள், அதிகரிப்புகள் மற்றும் பதில் தரத்தை நிர்வகிக்கவும்.',
  'Manage admin roles, access levels, team members, and security permissions.' => 'நிர்வாகப் பாத்திரங்கள், அணுகல் நிலைகள், குழு உறுப்பினர்கள் மற்றும் பாதுகாப்பு அனுமதிகளை நிர்வகிக்கவும்.',
  'Configure platform preferences, integrations, security, storage, and system behavior.' => 'இயங்குதள விருப்பத்தேர்வுகள், ஒருங்கிணைப்புகள், பாதுகாப்பு, சேமிப்பு மற்றும் கணினி நடத்தை ஆகியவற்றை உள்ளமைக்கவும்.',
