  'Use Shorts for discovery' => 'கண்டுபிடிப்புக்கு Shorts ஐப் பயன்படுத்தவும்',
  'Keep testing quick hooks and link viewers to longer videos.' => 'விரைவான கொக்கிகளைச் சோதித்து, நீண்ட வீடியோக்களுக்கு பார்வையாளர்களை இணைக்கவும்.',
  'Create short vertical videos to reach viewers who have not found your channel yet.' => 'இதுவரை உங்கள் சேனலைக் கண்டறியாத பார்வையாளர்களைச் சென்றடைய, குறுகிய செங்குத்து வீடியோக்களை உருவாக்கவும்.',
  'Create short' => 'சுருக்கமாக உருவாக்கவும்',
  'Turn comments into loyalty' => 'கருத்துகளை விசுவாசமாக மாற்றவும்',
  'Reply to recent comments and turn viewers into returning fans.' => 'சமீபத்திய கருத்துகளுக்குப் பதிலளித்து, பார்வையாளர்களை மீண்டும் ரசிகர்களாக மாற்றவும்.',
  'Ask a question in your next upload and reply quickly when comments arrive.' => 'உங்கள் அடுத்த பதிவேற்றத்தில் ஒரு கேள்வியைக் கேளுங்கள் மற்றும் கருத்துகள் வரும்போது விரைவாக பதிலளிக்கவும்.',
  'View comments' => 'கருத்துகளைப் பார்க்கவும்',
  'Improve public reach' => 'பொது அணுகலை மேம்படுத்தவும்',
  'Keep strong videos visible and refresh weak titles.' => 'வலுவான வீடியோக்களைக் காணவும், பலவீனமான தலைப்புகளைப் புதுப்பிக்கவும்.',
  'Explore tools' => 'கருவிகளை ஆராயுங்கள்',
  'Open the right workflow fast' => 'சரியான பணிப்பாய்வுகளை விரைவாக திறக்கவும்',
