  'Start a new upload with titles, tags, visibility, and thumbnail steps.' => 'தலைப்புகள், குறிச்சொற்கள், தெரிவுநிலை மற்றும் சிறுபட படிகளுடன் புதிய பதிவேற்றத்தைத் தொடங்கவும்.',
  'Shorts studio' => 'ஷார்ட்ஸ் ஸ்டுடியோ',
  'Create short videos for faster discovery and mobile viewers.' => 'விரைவான கண்டுபிடிப்பு மற்றும் மொபைல் பார்வையாளர்களுக்கு குறுகிய வீடியோக்களை உருவாக்கவும்.',
  'Content manager' => 'உள்ளடக்க மேலாளர்',
  'Review visibility, monetization, comments, and performance in one place.' => 'ஒரே இடத்தில் தெரிவுநிலை, பணமாக்குதல், கருத்துகள் மற்றும் செயல்திறன் ஆகியவற்றை மதிப்பாய்வு செய்யவும்.',
  'Analytics review' => 'பகுப்பாய்வு ஆய்வு',
  'Track views, likes, comments, publishing status, and trends.' => 'பார்வைகள், விருப்பங்கள், கருத்துகள், வெளியீட்டு நிலை மற்றும் போக்குகளைக் கண்காணிக்கவும்.',
  'Channel profile' => 'சேனல் சுயவிவரம்',
  'Update your bio, channel details, and public creator presence.' => 'உங்கள் பயோ, சேனல் விவரங்கள் மற்றும் பொது கிரியேட்டர் இருப்பை புதுப்பிக்கவும்.',
  'Audience building' => 'பார்வையாளர்களின் கட்டிடம்',
  'Study subscribers, comments, and what viewers respond to most.' => 'சந்தாதாரர்கள், கருத்துகள் மற்றும் பார்வையாளர்கள் அதிகம் பதிலளிக்கும் விஷயங்களைப் படிக்கவும்.',
  'Top content to learn from' => 'கற்றுக்கொள்ள வேண்டிய சிறந்த உள்ளடக்கம்',
  'Upload videos to unlock performance lessons.' => 'செயல்திறன் பாடங்களைத் திறக்க வீடியோக்களைப் பதிவேற்றவும்.',
  'Tips to reach more viewers' => 'அதிகமான பார்வையாளர்களைச் சென்றடைவதற்கான உதவிக்குறிப்புகள்',
  'Creator checklist' => 'படைப்பாளர் சரிபார்ப்பு பட்டியல்',
  'Hook viewers in the first 3 seconds' => 'முதல் 3 வினாடிகளில் பார்வையாளர்களை கவர்ந்திழுக்கவும்',
  'Open with the result, conflict, or visual payoff before adding context.' => 'சூழலைச் சேர்ப்பதற்கு முன் முடிவு, முரண்பாடு அல்லது காட்சிப் பலன்களுடன் திறக்கவும்.',
  'Make titles searchable' => 'தலைப்புகளைத் தேடக்கூடியதாக ஆக்குங்கள்',
  'Use the exact words viewers would type, then keep the promise in the video.' => 'பார்வையாளர்கள் தட்டச்சு செய்யும் சரியான வார்த்தைகளைப் பயன்படுத்தவும், பின்னர் வீடியோவில் வாக்குறுதியைக் காப்பாற்றவும்.',
  'Convert shorts into sessions' => 'குறும்படங்களை அமர்வுகளாக மாற்றவும்',
  'Pin a comment or description link from each short to a related full video.' => 'ஒவ்வொரு குறும்படத்திலிருந்தும் தொடர்புடைய முழு வீடியோவிற்கு ஒரு கருத்து அல்லது விளக்க இணைப்பைப் பின் செய்யவும்.',
  'Refresh underperforming uploads' => 'குறைவாகச் செயல்படும் பதிவேற்றங்களைப் புதுப்பிக்கவும்',
  'Update thumbnails and titles after you have enough impressions to compare.' => 'சிறுபடங்கள் மற்றும் தலைப்புகளை ஒப்பிட்டுப் பார்க்க போதுமான பதிவுகள் கிடைத்த பிறகு புதுப்பிக்கவும்.',
  'Upload source' => 'ஆதாரத்தைப் பதிவேற்றவும்',
  'Choose a local video file or import a public video from an enabled provider.' => 'உள்ளூர் வீடியோ கோப்பைத் தேர்வு செய்யவும் அல்லது இயக்கப்பட்ட வழங்குநரிடமிருந்து பொது வீடியோவை இறக்குமதி செய்யவும்.',
  'Local upload' => 'உள்ளூர் பதிவேற்றம்',
