  'Video import provider is disabled.' => 'வீடியோ இறக்குமதி வழங்குநர் முடக்கப்பட்டுள்ளது.',
  'Direct imports must use a supported video file URL.' => 'நேரடி இறக்குமதிகள் ஆதரிக்கப்படும் வீடியோ கோப்பு URL ஐப் பயன்படுத்த வேண்டும்.',
  'Cannot open remote video URL.' => 'ரிமோட் வீடியோ URLஐ திறக்க முடியவில்லை.',
  'Cannot prepare imported video file.' => 'இறக்குமதி செய்யப்பட்ட வீடியோ கோப்பைத் தயாரிக்க முடியாது.',
  'Cannot read remote video file.' => 'தொலை வீடியோ கோப்பைப் படிக்க முடியவில்லை.',
  'Imported video exceeds the maximum upload size.' => 'இறக்குமதி செய்யப்பட்ட வீடியோ அதிகபட்ச பதிவேற்ற அளவை விட அதிகமாக உள்ளது.',
  'Remote video file is empty.' => 'தொலைநிலை வீடியோ கோப்பு காலியாக உள்ளது.',
  'Video import downloader command is not configured.' => 'வீடியோ இறக்குமதி பதிவிறக்கி கட்டளை கட்டமைக்கப்படவில்லை.',
  'Downloader did not create an importable video file.' => 'பதிவிறக்கம் செய்பவர் இறக்குமதி செய்யக்கூடிய வீடியோ கோப்பை உருவாக்கவில்லை.',
  'Import URL is invalid.' => 'இறக்குமதி URL தவறானது.',
