  'Import URL does not match the selected provider.' => 'இறக்குமதி URL தேர்ந்தெடுக்கப்பட்ட வழங்குநருடன் பொருந்தவில்லை.',
  'Import URL host cannot be resolved.' => 'இறக்குமதி URL ஹோஸ்டைத் தீர்க்க முடியாது.',
  'Import URL must resolve to a public host.' => 'இறக்குமதி URL பொது ஹோஸ்டுக்குத் தீர்க்கப்பட வேண்டும்.',
  'Unknown video import provider.' => 'அறியப்படாத வீடியோ இறக்குமதி வழங்குநர்.',
  'Saves a public video file URL and plays it from the original URL.' => 'பொது வீடியோ கோப்பு URL ஐச் சேமித்து அசல் URL இலிருந்து இயக்குகிறது.',
  'Fetches YouTube details and plays with the YouTube embed player.' => 'YouTube விவரங்களைப் பெற்று, YouTube உட்பொதி பிளேயருடன் விளையாடுகிறது.',
