  'Fetches Dailymotion details and plays with the Dailymotion embed player.' => 'டெய்லிமோஷன் விவரங்களைப் பெற்று, டெய்லிமோஷன் உட்பொதி பிளேயருடன் விளையாடுகிறது.',
  'Select an enabled service and paste a public video URL. PlayHub will fetch the details and play it from the original provider.' => 'இயக்கப்பட்ட சேவையைத் தேர்ந்தெடுத்து, பொது வீடியோ URLஐ ஒட்டவும். PlayHub விவரங்களைப் பெற்று அசல் வழங்குநரிடமிருந்து அதை இயக்கும்.',
